import pandas as pd
import numpy as np
from pymatgen.core import Structure
from pymatgen.symmetry.analyzer import SpacegroupAnalyzer
from collections import defaultdict
import warnings
warnings.filterwarnings('ignore')

train = pd.read_csv('nlo_dn_train.csv')
pool = pd.read_csv('nlo_pool.csv')

def neighbor_stats(s, cutoff=3.2):
    """Look at short bonds to infer dimensionality of anion network"""
    # Get all pairwise distances
    dmat = s.distance_matrix
    species = [str(sp.specie) for sp in s]
    # Anions typically S, Se, Te, As, Sb, P, I, Br, Cl
    anions = {'S','Se','Te','As','Sb','P','I','Br','Cl','O','N','C'}
    # Count anion-anion short contacts (chains/rings)
    aa_bonds = []
    for i in range(len(s)):
        for j in range(i+1, len(s)):
            if species[i] in anions and species[j] in anions:
                if dmat[i,j] < cutoff:
                    aa_bonds.append((species[i], species[j], dmat[i,j]))
    return aa_bonds

print('=== Anion-anion contacts in top TRAIN ===')
for i, row in train.iterrows():
    if row['dn'] < 0.3:
        continue
    s = Structure.from_str(row['poscar'], fmt='poscar')
    # try multiple cutoffs
    for cut in [2.6, 2.8, 3.0, 3.3]:
        bonds = neighbor_stats(s, cut)
        if bonds:
            print(f"dn={row['dn']:.3f} {row['formula']:20s} cut={cut} n_aa={len(bonds)} e.g. {bonds[:6]}")
            break
    else:
        print(f"dn={row['dn']:.3f} {row['formula']:20s} NO anion-anion contacts < 3.3")

print('\n=== Anion-anion contacts in interesting POOL ===')
interest = ['c007','c089','c064','c087','c055','c049','c039','c069','c038','c079','c073','c066','c074','c061','c062','c090','c092','c080','c020','c036','c004']
for i, row in pool.iterrows():
    if row['candidate_id'] not in interest:
        continue
    s = Structure.from_str(row['poscar'], fmt='poscar')
    for cut in [2.6, 2.8, 3.0, 3.3]:
        bonds = neighbor_stats(s, cut)
        if bonds:
            print(f"{row['candidate_id']} {row['formula']:22s} cut={cut} n_aa={len(bonds)} e.g. {[(a,b,round(d,2)) for a,b,d in bonds[:8]]}")
            break
    else:
