import pandas as pd
import numpy as np
from pymatgen.core import Structure
from pymatgen.symmetry.analyzer import SpacegroupAnalyzer
import warnings
warnings.filterwarnings('ignore')

train = pd.read_csv('nlo_dn_train.csv')
pool = pd.read_csv('nlo_pool.csv')

# Typical homoatomic anion bond cutoffs
cutoffs = {
    'S': 2.35, 'Se': 2.60, 'Te': 3.05,
    'As': 2.70, 'Sb': 3.05, 'P': 2.40,
    'I': 3.0, 'Br': 2.6, 'Cl': 2.3,
    'O': 1.7, 'N': 1.7, 'C': 1.7, 'Si': 2.5, 'B': 1.9,
    'Sn': 3.1, 'Ge': 2.7, 'Ga': 2.7, 'In': 3.0, 'Al': 2.7,
    'Bi': 3.2, 'Pb': 3.2, 'Tl': 3.5,
}

def homo_anion_bonds(s):
    dmat = s.distance_matrix
    species = [str(sp.specie) for sp in s]
    bonds = []
    for i in range(len(s)):
        for j in range(i+1, len(s)):
            if species[i] == species[j]:
                cut = cutoffs.get(species[i], 0)
                if cut and dmat[i,j] < cut:
                    bonds.append((species[i], dmat[i,j]))
    return bonds

print('=== ALL POOL with homoatomic short bonds ===')
for i, row in pool.iterrows():
    s = Structure.from_str(row['poscar'], fmt='poscar')
    bonds = homo_anion_bonds(s)
    sga = SpacegroupAnalyzer(s, symprec=0.1)
    cs = sga.get_crystal_system()
    if bonds:
        kinds = {}
        for el, d in bonds:
            kinds.setdefault(el, []).append(d)
        summary = {el: (len(ds), round(min(ds),2), round(max(ds),2)) for el,ds in kinds.items()}
        print(f"{row['candidate_id']} {row['formula']:22s} {cs:13s} {summary}")

print('\n=== TRAIN homoatomic bonds vs dn ===')
results = []
for i, row in train.iterrows():
    s = Structure.from_str(row['poscar'], fmt='poscar')
    bonds = homo_anion_bonds(s)
    kinds = {}
    for el, d in bonds:
        kinds.setdefault(el, []).append(d)
    if bonds:
        summary = {el: len(ds) for el,ds in kinds.items()}
        results.append((row['dn'], row['formula'], summary))

for dn, f, sm in sorted(results, reverse=True):
    print(f"dn={dn:.3f} {f:22s} {sm}")
